function buildNetworkMap(){
  const map=new Uint8Array(NETWORK_MAP_SIZE*NETWORK_MAP_SIZE),setWall=(x,y,v=1)=>{if(x>=0&&x<NETWORK_MAP_SIZE&&y>=0&&y<NETWORK_MAP_SIZE)map[y*NETWORK_MAP_SIZE+x]=v;};
  for(let i=0;i<NETWORK_MAP_SIZE;i++){setWall(i,0);setWall(i,NETWORK_MAP_SIZE-1);setWall(0,i);setWall(NETWORK_MAP_SIZE-1,i);}
  const lines=[25,50,75,100,125];
  lines.forEach((x,li)=>{for(let y=1;y<NETWORK_MAP_SIZE-1;y++){const sector=Math.floor(y/25),local=y%25,ds=((sector+li)%2===0)?6:16;if(local<ds||local>ds+2)setWall(x,y);}});
  lines.forEach((y,li)=>{for(let x=1;x<NETWORK_MAP_SIZE-1;x++){const sector=Math.floor(x/25),local=x%25,ds=((sector+li+1)%2===0)?6:16;if(local<ds||local>ds+2)setWall(x,y);}});
  for(let sy=0;sy<6;sy++)for(let sx=0;sx<6;sx++){if(sx===3&&sy===3)continue;if((sx+sy)%2!==0)continue;const cx=sx*25+13,cy=sy*25+13,h=((sx*3+sy)%2)===0,w=h?5:2,hh=h?2:5;for(let oy=-Math.floor(hh/2);oy<=Math.floor(hh/2);oy++)for(let ox=-Math.floor(w/2);ox<=Math.floor(w/2);ox++)setWall(cx+ox,cy+oy);}
  for(let y=70;y<=80;y++)for(let x=70;x<=80;x++)setWall(x,y,0);
  for(const o of [...NETWORK_OBJECT_DEFS,...NETWORK_VENT_DEFS]){const cx=Math.floor(o.x),cy=Math.floor(o.y);for(let y=cy-1;y<=cy+1;y++)for(let x=cx-1;x<=cx+1;x++)setWall(x,y,0);}
  return map;
}
const NETWORK_MAP_DATA=buildNetworkMap();
let worldWallLayer=null,worldWallLayerTheme='';
function ensureWorldWallLayer(p){
  const theme=document.documentElement.dataset.theme==='dark'?'dark':'light';
  if(worldWallLayer&&worldWallLayerTheme===theme)return worldWallLayer;
  const c=document.createElement('canvas');c.width=c.height=600;const x=c.getContext('2d',{alpha:false}),s=c.width/NETWORK_MAP_SIZE;
  x.fillStyle=p.floor;x.fillRect(0,0,c.width,c.height);x.fillStyle=p.wall;
  for(let row=0;row<NETWORK_MAP_SIZE;row++)for(let col=0;col<NETWORK_MAP_SIZE;col++)if(NETWORK_MAP_DATA[row*NETWORK_MAP_SIZE+col]===1)x.fillRect(col*s,row*s,Math.ceil(s),Math.ceil(s));
  worldWallLayer=c;worldWallLayerTheme=theme;return c;
}function buildMap(){
  const map=new Uint8Array(MAP_SIZE*MAP_SIZE);
  for(let row=0;row<MAP_SIZE;row++)for(let col=0;col<MAP_SIZE;col++){
    const nx=Math.min(NETWORK_MAP_SIZE-1,Math.floor((col+.5)*CLIENT_TO_NETWORK));
    const ny=Math.min(NETWORK_MAP_SIZE-1,Math.floor((row+.5)*CLIENT_TO_NETWORK));
    map[row*MAP_SIZE+col]=NETWORK_MAP_DATA[ny*NETWORK_MAP_SIZE+nx];
  }
  for(const o of [...OBJECT_DEFS,...VENT_DEFS]){const cx=Math.floor(o.x),cy=Math.floor(o.y);for(let y=cy-1;y<=cy+1;y++)for(let x=cx-1;x<=cx+1;x++)if(x>=0&&x<MAP_SIZE&&y>=0&&y<MAP_SIZE)map[y*MAP_SIZE+x]=0;}
  for(const [x,y] of DOOR_CELLS)if(x>=0&&x<MAP_SIZE&&y>=0&&y<MAP_SIZE)map[y*MAP_SIZE+x]=0;
  return map;
}
