function sendPacket(payload){if(!socket||socket.readyState!==WebSocket.OPEN)return false;try{socket.send(JSON.stringify(payload));return true;}catch(_){return false;}}
function flushPosition(force=false){if(!myPlayerId||gameState.phase!=='playing'||selfState.inVent||(!force&&!posDirty))return false;const ok=sendPacket({t:'pos',x:+toNetworkCoord(myPos.x).toFixed(3),y:+toNetworkCoord(myPos.y).toFixed(3)});if(ok){lastPosSendTime=performance.now();posDirty=false;}return ok;}
function sendAction(payload,syncPosition=true){if(networkPaused){showToast('Server 直连恢复后再操作');return false;}if(syncPosition)flushPosition(true);return sendPacket(payload);}
function networkPathLabel(){const net=window.__DTAM_NET__||{},v3=window.__DTAM_V3_TRANSPORT__||{};if(net.nativeActive)return 'Native '+String(net.nativePath||'P2P').toUpperCase();if(v3.direct)return v3.label||'Server 直连';if(v3.mode&&v3.mode!=='boot')return v3.mode==='direct'?'Server 直连':'Server 建链';if(net.relay)return'TURN';if(net.mode==='browser-host'||net.mode==='p2p-recovered-host')return'房主';if(net.mode==='p2p-direct')return'P2P';if(net.mode==='server-fallback')return'Server';return String(net.mode||'网络');}
