function renderLatency(){if(!latencyStatus)return;const current=effectiveLatency(),path=networkPathLabel();latencyStatus.dataset.path=path;if(!Number.isFinite(current.rtt)){latencyStatus.textContent=current.host?'本机':'-- ms';latencyStatus.dataset.quality=current.host?'local':'unknown';latencyStatus.removeAttribute('data-rtt');latencyStatus.removeAttribute('data-jitter');latencyStatus.title=current.host?'浏览器房主本机权威；有玩家后显示最慢直连 RTT':path+' · 等待有效 RTT 样本';return;}const r=Math.max(0,Math.round(current.rtt)),j=Number.isFinite(networkJitterMs)?Math.max(0,Math.round(networkJitterMs)):0,q=r<80?'good':r<160?'fair':r<300?'poor':'bad';latencyStatus.textContent=r+' ms';latencyStatus.dataset.quality=q;latencyStatus.dataset.rtt=String(r);latencyStatus.dataset.jitter=String(j);latencyStatus.title=path+' · RTT '+r+' ms · 抖动 ±'+j+' ms';}
