function openTask(task){if(!task)return;clearTimeout(taskRequestTimer);activeTaskId=task.id;activeTaskChallenge=null;taskMode='task';taskModalTitle.textContent=task.label;taskEyebrow.textContent='任务';taskModalBody.innerHTML='<p>正在获取任务内容…</p>';taskMeter.hidden=true;taskHoldBtn.hidden=true;taskModal.classList.add('show');keys={};resetJoy();if(!sendAction({t:'task_begin',id:task.id})){closeTask();showToast('连接未就绪，请重试');return;}taskRequestTimer=setTimeout(()=>{if(taskMode==='task'&&activeTaskId&&!activeTaskChallenge){closeTask();showToast('任务点状态已变化，请靠近后重试',2200);}},2600);}
function openRepair(station){if(!station)return;activeRepairStation=station.id;activeTaskId='';activeTaskChallenge=null;taskMode='repair';taskModalTitle.textContent=station.label;taskEyebrow.textContent='紧急修复';taskModalBody.innerHTML=`<p>保持操作以修复 ${escapeHtml(gameState.sabotage?.label||'破坏')}。</p>`;taskMeter.hidden=false;taskMeterFill.style.width='0%';taskHoldBtn.hidden=false;taskHoldBtn.textContent='按住修复';taskModal.classList.add('show');keys={};resetJoy();}
function closeTask(){clearTimeout(taskRequestTimer);taskRequestTimer=null;activeTaskId='';activeRepairStation='';activeTaskChallenge=null;taskSequenceInput=[];taskHoldStart=0;cancelAnimationFrame(taskHoldRAF);taskModal.classList.remove('show');taskMeterFill.style.width='0%';taskModalBody.innerHTML='';}
function renderTaskChallenge(c){activeTaskChallenge=c;taskMode='task';taskEyebrow.textContent='任务';taskModalTitle.textContent=c.label||objById(c.id)?.label||'任务';taskMeter.hidden=true;taskHoldBtn.hidden=true;taskSequenceInput=[];const payload=c.payload||{};if(c.type==='hold'){taskModalBody.innerHTML='<p>按住按钮直到进度完成。</p>';taskMeter.hidden=false;taskHoldBtn.hidden=false;taskHoldBtn.textContent='按住处理';return;}if(c.type==='sequence'){const seq=Array.isArray(payload.sequence)?payload.sequence:[];taskModalBody.innerHTML=`<p>按给定顺序输入：</p><div class="sequence-target">${seq.map(n=>n+1).join(' → ')}</div><div class="sequence-buttons">${[0,1,2,3].map(n=>`<button type="button" data-seq="${n}">${n+1}</button>`).join('')}</div><div id="sequenceStatus">已输入 0 / ${seq.length}</div>`;taskModalBody.querySelectorAll('[data-seq]').forEach(btn=>btn.onclick=()=>handleSequence(Number(btn.dataset.seq)));return;}if(c.type==='keypad'){const code=String(payload.code||'');taskModalBody.innerHTML=`<p>将屏幕上的代码输入终端：</p><div class="keypad-code">${escapeHtml(code)}</div><input id="taskKeypadInput" inputmode="numeric" maxlength="4" placeholder="输入 4 位代码"><button id="taskSubmitBtn" type="button">确认代码</button>`;$('taskSubmitBtn').onclick=()=>submitTaskAnswer($('taskKeypadInput').value);return;}if(c.type==='align'){const target=Number(payload.target||50);taskModalBody.innerHTML=`<p>将信号调到目标值 <strong>${target}</strong>（±4）。</p><input id="taskAlignInput" type="range" min="0" max="100" value="50"><div id="taskAlignValue">50</div><button id="taskSubmitBtn" type="button">锁定信号</button>`;const r=$('taskAlignInput'),v=$('taskAlignValue');r.oninput=()=>v.textContent=r.value;$('taskSubmitBtn').onclick=()=>submitTaskAnswer(r.value);return;}}
function handleSequence(n){if(!activeTaskChallenge||activeTaskChallenge.type!=='sequence')return;const seq=activeTaskChallenge.payload?.sequence||[],expected=seq[taskSequenceInput.length];if(n!==expected){taskSequenceInput=[];const st=$('sequenceStatus');if(st)st.textContent=`顺序错误，重新开始 · 0 / ${seq.length}`;return;}taskSequenceInput.push(n);const st=$('sequenceStatus');if(st)st.textContent=`已输入 ${taskSequenceInput.length} / ${seq.length}`;if(taskSequenceInput.length===seq.length)submitTaskAnswer(taskSequenceInput.join(','));}
function submitTaskAnswer(answer){const c=activeTaskChallenge;if(!c)return;sendAction({t:'task_complete',id:c.id,token:c.token,answer:String(answer)});taskModalBody.querySelectorAll('button,input').forEach(el=>el.disabled=true);}
function tickTaskHold(){if(!taskHoldStart)return;const duration=taskMode==='repair'?950:Number(activeTaskChallenge?.payload?.duration||1200),pct=clamp((performance.now()-taskHoldStart)/duration,0,1);taskMeterFill.style.width=`${pct*100}%`;if(pct>=1){taskHoldStart=0;cancelAnimationFrame(taskHoldRAF);if(taskMode==='repair'){const stationId=activeRepairStation;closeTask();sendAction({t:'sabotage_fix',stationId});}else if(activeTaskChallenge){submitTaskAnswer('ok');}return;}taskHoldRAF=requestAnimationFrame(tickTaskHold);}
