function pruneVoiceDirectory(){const active=new Set(voiceDirectory.filter(v=>v.playerId!==myPlayerId&&v.enabled&&v.connected&&v.sessionId&&v.trackName&&voicePeerAllowed(v)).map(v=>v.sessionId+'|'+v.trackName));for(const [key,a] of voiceRemoteAudios){if(!active.has(key)){try{a.srcObject=null;a.remove();}catch(_){}voiceRemoteAudios.delete(key);voiceSubscribed.delete(key);}}for(const key of [...voiceSubscribed.keys()])if(!active.has(key))voiceSubscribed.delete(key);}
