async function rebuildVoiceTransport(){if(!voiceDesired||!voiceLocalStream?.getAudioTracks?.()[0])return;voiceStarting=true;setMicUi();try{try{voiceSendPc?.close()}catch(_){}try{voiceRecvPc?.close()}catch(_){}clearRemoteVoice();voiceSendPc=voiceRecvPc=null;voiceSendSession=voiceRecvSession='';const track=voiceLocalStream.getAudioTracks()[0];voiceSendSession=(await voiceApi('/sessions/new')).sessionId;voiceSendPc=newVoicePc();const tx=voiceSendPc.addTransceiver(track,{direction:'sendonly'}),offer=await voiceSendPc.createOffer();await voiceSendPc.setLocalDescription(offer);const pushed=await voiceApi('/sessions/'+encodeURIComponent(voiceSendSession)+'/tracks/new','POST',{sessionDescription:{sdp:offer.sdp,type:'offer'},tracks:[{location:'local',mid:tx.mid,trackName:track.id}]});if(pushed.sessionDescription)await voiceSendPc.setRemoteDescription(pushed.sessionDescription);voiceRecvSession=(await voiceApi('/sessions/new')).sessionId;voiceRecvPc=newVoicePc();voiceRecvPc.addEventListener('track',e=>{const entry=voicePendingMids.get(String(e.transceiver?.mid||'')),key=entry?(entry.sessionId+'|'+entry.trackName):('track|'+e.track.id);if(entry&&!voicePeerAllowed(entry)){try{e.track.stop();}catch(_){}voiceSubscribed.delete(key);return;}let a=voiceRemoteAudios.get(key);if(!a){a=document.createElement('audio');a.autoplay=true;a.playsInline=true;a.dataset.voiceKey=key;voiceSink.appendChild(a);voiceRemoteAudios.set(key,a);}a.srcObject=new MediaStream([e.track]);a.play().then(()=>{voiceUnlockBtn.hidden=true;}).catch(()=>{voiceUnlockBtn.hidden=false;});e.track.addEventListener('ended',()=>{a.remove();voiceRemoteAudios.delete(key);voiceSubscribed.delete(key);},{once:true});});voiceActive=true;sendPacket({t:'voice_publish',sessionId:voiceSendSession,trackName:track.id,enabled:track.enabled});scheduleVoiceDirectory();}finally{voiceStarting=false;setMicUi();}}
async function startVoice(){if(voiceStarting)return;voiceDesired=true;try{await unlockVoicePlayback();if(!window.isSecureContext)throw Object.assign(new Error('语音需要 HTTPS 安全连接'),{name:'SecurityError'});if(!navigator.mediaDevices?.getUserMedia)throw new Error('此浏览器不支持麦克风采集');if(typeof RTCPeerConnection!=='function')throw new Error('此浏览器不支持 WebRTC 语音');if(!voiceLocalStream||!voiceLocalStream.getAudioTracks()[0]||voiceLocalStream.getAudioTracks()[0].readyState==='ended'){try{voiceLocalStream=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:true,noiseSuppression:true,autoGainControl:true},video:false});}catch(e){if(e?.name==='OverconstrainedError'||e?.name==='ConstraintNotSatisfiedError')voiceLocalStream=await navigator.mediaDevices.getUserMedia({audio:true,video:false});else throw e;}}const track=voiceLocalStream.getAudioTracks()[0];if(!track)throw new Error('未获得麦克风音轨');track.enabled=true;await rebuildVoiceTransport();showToast('语音已开启');}catch(e){voiceDesired=false;stopVoice();showToast('无法开启麦克风：'+voiceErrorMessage(e),3600);}setMicUi();}
function toggleVoice(){unlockVoicePlayback().catch(()=>{});if(!voiceDesired||!voiceLocalStream||!voiceActive){startVoice();return;}const track=voiceLocalStream.getAudioTracks()[0];if(!track)return;track.enabled=!track.enabled;sendPacket({t:'voice_state',enabled:track.enabled});setMicUi();}
