[ruleNormalImpostors,ruleShapeshifters,rulePhantoms,ruleVipers,ruleEngineers,ruleScientists,ruleTrackers,ruleNoisemakers,ruleDetectives,ruleGuardianAngels,ruleTasks,ruleSpeed,ruleKill,ruleDiscussion,ruleVoting,ruleEmergency,ruleSabotage,ruleMusicControl,ruleConfirm].forEach(el=>el.addEventListener('change',()=>{const v=currentRules(),imp=v.normalImpostors+v.shapeshifters+v.phantoms+v.vipers,crew=v.engineers+v.scientists+v.trackers+v.noisemakers+v.detectives,guardians=v.guardianAngels,count=Object.values(players).filter(p=>p.connected).length,capacity=roleCapacity(v,count);impRoleSummary.textContent='总数 '+imp;crewRoleSummary.textContent=(crew?'开局特殊职业 '+crew:'其余为普通船员')+(guardians?' · 守护上限 '+guardians:'');roleCountNote.textContent=capacity.message;roleCountNote.dataset.state=capacity.ok?'ok':'error';startGameBtn.disabled=!capacity.ok;sendRules();}));
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(taskModal.classList.contains('show'))closeTask();else if(sabotageOverlay.classList.contains('show'))closeSabotage();else if(infoOverlay.classList.contains('show'))closeInfo();else if(chatVisible)toggleChat(false);else if(playerPanelVisible)togglePlayerPanel(false);}});

